steps.seedCode:
import React, { useState } from 'react';

// Create your ColorPicker component here
const ColorPicker = () => {
  // Initialize color state here
  const [color, setColor] = useState<string>('#ff0000');

  // Define handleColorChange function here
  const handleColorChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setColor(e.target.value);
  };

  return (
    <div>
      {/* Add h1 element here */}
      <h1>Color Picker</h1>
      {/* Add color preview div here */}
      <div
        style={{
          width: '100px',
          height: '100px',
          backgroundColor: color,
          margin: '20px auto',
          border: '2px solid #333'
        }}
      />
      {/* Add color input here */}
      <label htmlFor="colorInput">Choose a color:</label>
      <input
        id="colorInput"
        type="color"
        value={color}
        onChange={handleColorChange}
      />
    </div>
  );
};
